{"content":"#!/usr/bin/env python3
"""UCI-compliant chess engine.

Strength: negamax alpha-beta with iterative deepening, transposition table,
MVV-LVA + killer move ordering, quiescence search, and a material +
piece-square evaluation. Handles the full UCI subset used by the harness:
`position fen <fen> [moves ...]`, `position startpos [moves ...]`, `go`,
plus `uci`, `isready`, `quit`.
"""

import sys
import time

import chess

MATE = 100000
INF = 10 ** 9
# Soft search budget; the harness kills us at 2.0s including interpreter
# startup, so leave a comfortable margin.
TIME_LIMIT = 1.5
MAX_DEPTH = 6  # hard cap for iterative deepening (endgames only)

PIECE_VALUES = {
    chess.PAWN: 100,
    chess.KNIGHT: 320,
    chess.BISHOP: 330,
    chess.ROOK: 500,
    chess.QUEEN: 950,
    chess.KING: 0,
}

# Tables listed rank8 -> rank1 (a8..h1), from White's perspective.
PAWN_T = [
    0, 0, 0, 0, 0, 0, 0, 0,
    50, 50, 50, 50, 50, 50, 50, 50,
    10, 10, 20, 30, 30, 20, 10, 10,
    5, 5, 10, 25, 25, 10, 5, 5,
    0, 0, 0, 20, 20, 0, 0, 0,
    5, -5, -10, 0, 0, -10, -5, 5,
    5, 10, 10, -20, -20, 10, 10, 5,
    0, 0, 0, 0, 0, 0, 0, 0,
]
KNIGHT_T = [
    -50, -40, -30, -30, -30, -30, -40, -50,
    -40, -20, 0, 0, 0, 0, -20, -40,
    -30, 0, 10, 15, 15, 10, 0, -30,
    -30, 5, 15, 20, 20, 15, 5, -30,
    -30, 0, 15, 20, 20, 15, 0, -30,
    -30, 5, 10, 15, 15, 10, 5, -30,
    -40, -20, 0, 5, 5, 0, -20, -40,
    -50, -40, -30, -30, -30, -30, -40, -50,
]
BISHOP_T = [
    -20, -10, -10, -10, -10, -10, -10, -20,
    -10, 0, 0, 0, 0, 0, 0, -10,
    -10, 0, 5, 10, 10, 5, 0, -10,
    -10, 5, 5, 10, 10, 5, 5, -10,
    -10, 0, 10, 10, 10, 10, 0, -10,
    -10, 10, 10, 10, 10, 10, 10, -10,
    -10, 5, 0, 0, 0, 0, 5, -10,
    -20, -10, -10, -10, -10, -10, -10, -20,
]
ROOK_T = [
    0, 0, 0, 0, 0, 0, 0, 0,
    5, 10, 10, 10, 10, 10, 10, 5,
    -5, 0, 0, 0, 0, 0, 0, -5,
    -5, 0, 0, 0, 0, 0, 0, -5,
    -5, 0, 0, 0, 0, 0, 0, -5,
    -5, 0, 0, 0, 0, 0, 0, -5,
    -5, 0, 0, 0, 0, 0, 0, -5,
    0, 0, 0, 5, 5, 0, 0, 0,
]
QUEEN_T = [
    -20, -10, -10, -5, -5, -10, -10, -20,
    -10, 0, 0, 0, 0, 0, 0, -10,
    -10, 0, 5, 5, 5, 5, 0, -10,
    -5, 0, 5, 5, 5, 5, 0, -5,
    0, 0, 5, 5, 5, 5, 0, -5,
    -10, 5, 5, 5, 5, 5, 0, -10,
    -10, 0, 5, 0, 0, 0, 0, -10,
    -20, -10, -10, -5, -5, -10, -10, -20,
]
KING_MID_T = [
    -30, -40, -40, -50, -50, -40, -40, -30,
    -30, -40, -40, -50, -50, -40, -40, -30,
    -30, -40, -40, -50, -50, -40, -40, -30,
    -30, -40, -40, -50, -50, -40, -40, -30,
    -20, -30, -30, -40, -40, -30, -30, -20,
    -10, -20, -20, -20, -20, -20, -20, -10,
    20, 20, 0, 0, 0, 0, 20, 20,
    20, 30, 10, 0, 0, 10, 30, 20,
]
KING_END_T = [
    -50, -40, -30, -20, -20, -30, -40, -50,
    -30, -20, -10, 0, 0, -10, -20, -30,
    -30, -10, 20, 30, 30, 20, -10, -30,
    -30, -10, 30, 40, 40, 30, -10, -30,
    -30, -10, 30, 40, 40, 30, -10, -30,
    -30, -10, 20, 30, 30, 20, -10, -30,
    -30, -30, 0, 0, 0, 0, -30, -30,
    -50, -30, -30, -30, -30, -30, -30, -50,
]

PST = {
    chess.PAWN: PAWN_T,
    chess.KNIGHT: KNIGHT_T,
    chess.BISHOP: BISHOP_T,
    chess.ROOK: ROOK_T,
    chess.QUEEN: QUEEN_T,
}


def _pst_index(square):
    """Convert a python-chess square (a1=0..h8=63) to a rank8-first table index."""
    rank = chess.square_rank(square)
    fil = chess.square_file(square)
    return (7 - rank) * 8 + fil


class TimeUp(Exception):
    pass


class Engine:
    def __init__(self):
        self.nodes = 0
        self.deadline = 0.0
        self.tt = {}
        self.killers = {}

    # ---------------- evaluation ----------------
    @staticmethod
    def evaluate(board):
        """Static eval from White's perspective (centipawns)."""
        if board.is_insufficient_material():
            return 0
        piece_map = board.piece_map()
        # Endgame king table when queens are gone or material is thin.
        queens = 0
        minor_major = 0
        for pc in piece_map.values():
            if pc.piece_type == chess.QUEEN:
                queens += 1
            elif pc.piece_type not in (chess.PAWN, chess.KING):
                minor_major += 1
        endgame = queens == 0 or (queens <= 2 and minor_major <= 2)
        king_table = KING_END_T if endgame else KING_MID_T

        score = 0
        bishops = [0, 0]  # white, black bishop count
        for sq, pc in piece_map.items():
            if pc.piece_type == chess.KING:
                table = king_table
            else:
                table = PST[pc.piece_type]
            idx = _pst_index(sq)
            val = PIECE_VALUES[pc.piece_type] + table[idx]
            if pc.color == chess.WHITE:
                score += val
            else:
                score -= val
            if pc.piece_type == chess.BISHOP:
                bishops[0 if pc.color == chess.WHITE else 1] += 1
        # Bishop pair bonus.
        if bishops[0] >= 2:
            score += 30
        if bishops[1] >= 2:
            score -= 30
        return score

    def eval_negamax(self, board):
        s = self.evaluate(board)
        return s if board.turn == chess.WHITE else -s

    # ---------------- move ordering ----------------
    def order_moves(self, board, moves, tt_move, ply):
        scored = []
        kill = self.killers.get(ply, ())
        for m in moves:
            s = 0
            if tt_move is not None and m == tt_move:
                s = 1000000
            elif board.is_capture(m):
                victim = None
                if board.is_en_passant(m):
                    victim = chess.PAWN
                else:
                    target = board.piece_at(m.to_square)
                    if target:
                        victim = target.piece_type
                attacker = board.piece_at(m.from_square)
                att = attacker.piece_type if attacker else chess.PAWN
                v = PIECE_VALUES.get(victim, 0) if victim else 0
                s = 100000 + v * 10 - PIECE_VALUES.get(att, 0)
                if m.promotion:
                    s += PIECE_VALUES.get(m.promotion, 0)
            else:
                if m == kill[0] if len(kill) > 0 else False:
                    s = 90000
                elif len(kill) > 1 and m == kill[1]:
                    s = 80000
                if m.promotion:
                    s = 95000 + PIECE_VALUES.get(m.promotion, 0)
            scored.append((s, m))
        scored.sort(key=lambda x: x[0], reverse=True)
        return [m for _, m in scored]

    def check_time(self):
        self.nodes += 1
        if (self.nodes & 1023) == 0 and time.monotonic() > self.deadline:
            raise TimeUp()

    # ---------------- search ----------------
    def quiescence(self, board, alpha, beta, ply, qdepth=8):
        self.check_time()
        in_check = board.is_check()
        if board.is_insufficient_material() or board.halfmove_clock >= 100:
            return 0
        if in_check:
            moves = list(board.legal_moves)
            if not moves:
                return -MATE + ply  # checkmated
            if qdepth <= 0:
                return self.eval_negamax(board)
            ordered = self.order_moves(board, moves, None, ply)
            best = -INF
            for m in ordered:
                board.push(m)
                try:
                    v = -self.quiescence(board, -beta, -alpha, ply + 1, qdepth - 1)
                finally:
                    board.pop()
                if v > best:
                    best = v
                if best > alpha:
                    alpha = best
                if alpha >= beta:
                    break
            return best
        stand = self.eval_negamax(board)
        if stand >= beta:
            return beta
        if stand > alpha:
            alpha = stand
        if qdepth <= 0:
            return alpha
        captures = [m for m in board.legal_moves
                    if board.is_capture(m) or m.promotion]
        ordered = self.order_moves(board, captures, None, ply)
        for m in ordered:
            # Delta pruning: skip captures that cannot raise alpha.
            victim = 0
            if board.is_en_passant(m):
                victim = PIECE_VALUES[chess.PAWN]
            else:
                target = board.piece_at(m.to_square)
                if target:
                    victim = PIECE_VALUES.get(target.piece_type, 0)
            promo = PIECE_VALUES.get(m.promotion, 0) if m.promotion else 0
            if stand + victim + promo + 150 < alpha:
                continue
            board.push(m)
            try:
                v = -self.quiescence(board, -beta, -alpha, ply + 1, qdepth - 1)
            finally:
                board.pop()
            if v > alpha:
                alpha = v
            if alpha >= beta:
                break
        return alpha

    def negamax(self, board, depth, alpha, beta, ply):
        self.check_time()
        if board.is_insufficient_material() or board.halfmove_clock >= 100:
            return 0
        if board.is_repetition(2):
            return 0
        in_check = board.is_check()
        moves = list(board.legal_moves)
        if not moves:
            if in_check:
                return -MATE + ply  # checkmated (delivers/receives detection)
            return 0  # stalemate
        if depth <= 0:
            return self.quiescence(board, alpha, beta, ply)

        key = board.transposition_key()
        tt_move = None
        entry = self.tt.get(key)
        if entry is not None and entry[0] >= depth:
            _, val, flag, mv = entry
            if flag == 0:
                return val
            if flag == 1 and val >= beta:
                return val
            if flag == 2 and val <= alpha:
                return val
            tt_move = mv

        # Null-move pruning (safe: never in check, never in endgame/pawn-only,
        # never near mate, and verified by a full search afterwards via TT).
        if (not in_check and depth >= 3 and beta < MATE - 1000
                and any(board.piece_at(sq) is not None
                        and board.piece_at(sq).piece_type not in (chess.PAWN, chess.KING)
                        for sq in chess.SQUARES
                        if board.piece_at(sq) is not None
                        and board.piece_at(sq).color == board.turn)):
            board.push(chess.Move.null())
            try:
                v = -self.negamax(board, depth - 3, -beta, -beta + 1, ply + 1)
            finally:
                board.pop()
            if v >= beta:
                return beta

        ordered = self.order_moves(board, moves, tt_move, ply)
        best = -INF
        best_move = ordered[0]
        orig_alpha = alpha
        for m in ordered:
            board.push(m)
            try:
                v = -self.negamax(board, depth - 1, -beta, -alpha, ply + 1)
            finally:
                board.pop()
            if v > best:
                best = v
                best_move = m
            if best > alpha:
                alpha = best
            if alpha >= beta:
                # Killer heuristic for quiet moves.
                if not board.is_capture(m) and not m.promotion:
                    k = self.killers.get(ply, ())
                    if m not in k:
                        self.killers[ply] = (m,) + k[:1]
                break
        flag = 0
        if best <= orig_alpha:
            flag = 2
        elif best >= beta:
            flag = 1
        self.tt[key] = (depth, best, flag, best_move)
        return best

    def search(self, board):
        moves = list(board.legal_moves)
        if not moves:
            return None
        if len(moves) == 1:
            return moves[0]
        self.nodes = 0
        self.deadline = time.monotonic() + TIME_LIMIT
        self.tt = {}
        self.killers = {}
        # Cheap pre-sort so depth 1 already tries captures first.
        root_moves = self.order_moves(board, moves, None, 0)
        best = root_moves[0]
        # Adaptive max depth: low-branching endgames can search deeper.
        max_depth = 4 if len(moves) > 12 else MAX_DEPTH
        try:
            for depth in range(1, max_depth + 1):
                alpha = -INF
                beta = INF
                local_best = best
                local_best_val = -INF
                for m in root_moves:
                    board.push(m)
                    try:
                        v = -self.negamax(board, depth - 1, -beta, -alpha, 1)
                    finally:
                        board.pop()
                    if v > local_best_val:
                        local_best_val = v
                        local_best = m
                    if v > alpha:
                        alpha = v
                best = local_best
                # Move the new best to the front for the next iteration.
                root_moves.remove(best)
                root_moves.insert(0, best)
                # Stop early on a found forced mate.
                if local_best_val > MATE - 1000:
                    break
        except TimeUp:
            pass
        return best


def parse_position(board, args):
    """Apply `position ...` args to board. Returns the board."""
    if not args:
        return board
    if args[0] == "startpos":
        board = chess.Board()
        args = args[1:]
    elif args[0] == "fen":
        # FEN is 6 fields; an optional `moves ...` suffix may follow.
        if "moves" in args:
            mi = args.index("moves")
            fen = " ".join(args[1:mi])
            rest = args[mi + 1:]
        else:
            fen = " ".join(args[1:])
            rest = []
        board = chess.Board(fen)  # full FEN: pieces, turn, castling, EP, clocks
        for tok in rest:
            board.push_uci(tok)
        return board
    else:
        return board
    if args and args[0] == "moves":
        for tok in args[1:]:
            board.push_uci(tok)
    return board


def main():
    board = chess.Board()
    engine = Engine()
    data = sys.stdin
    for raw in data:
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        cmd = parts[0]
        if cmd == "uci":
            print("id name MyEngine")
            print("id author Muse")
            print("uciok", flush=True)
        elif cmd == "isready":
            print("readyok", flush=True)
        elif cmd == "setoption":
            continue
        elif cmd == "ucinewgame":
            board = chess.Board()
        elif cmd == "position":
            board = parse_position(board, parts[1:])
        elif cmd == "go":
            try:
                move = engine.search(board)
            except Exception:
                moves = list(board.legal_moves)
                move = moves[0] if moves else None
            if move is None:
                print("bestmove 0000", flush=True)
            else:
                print("bestmove " + move.uci(), flush=True)
        elif cmd == "stop":
            continue
        elif cmd == "quit":
            break


if __name__ == "__main__":
    main()
